{"code":"import pandas as pd, numpy as np, statsmodels.formula.api as smf
x=pd.read_csv('data/explore.csv'); cols=['vitamin_d','sleep_hours','steps_k','bmi','crp_level','dose_mg','age_decades','sodium_mmol','hdl','stress_index']
for c in cols:
 d=x[['recovery_score','hospital',c]].dropna(); m=smf.ols(f'recovery_score ~ {c} + C(hospital)',d).fit()
 print(c, round(m.params[c],3), round(m.pvalues[c],5), round(m.rsquared,3),len(d))
"}
